193	func (s Store) classifyReviewInterruption(run *ReviewRun, plan DispatchPlan, transcript []byte, runErr, ctxErr error) (string, string, error) {
194		// Inspect both supported output channels before any public publication.
195		channels := append([]string{string(transcript), run.Output}, plan.extraChannels...)
196		value, e := captureReviewChannels(sessionPattern(plan.Config), channels...)
197		if e != nil {
198			return "", "", e
199		}
200		if value != "" && plan.session != "" && value != plan.session {
201			return "", "", fmt.Errorf("adapter changed the captured session")
202		}
203		if value == "" {
204			value = plan.session
205		}
206		if value != "" {
207			run.sessionForRedaction = value
208			run.SessionDigest, e = s.saveReviewSession(value)
209			if e != nil {
210				return "", "", e
211			}
212		}
213		cause := ""
214		if ctxErr != nil {
215			cause = "timeout"
216			if errors.Is(ctxErr, context.Canceled) {
217				cause = "cancelled"
218			}
219		} else if runErr != nil && run.ExitCode < 0 {
220			cause = "process-lost"
221		}
222		limit := false
223		if p := plan.Config.Limit; p != nil {
224			for _, code := range p.ExitCodes {
225				if code == run.ExitCode {
226					limit = true
227				}
228			}
229			for _, pattern := range p.OutputPatterns {
230				for _, channel := range channels {
231					if regexp.MustCompile(pattern).MatchString(channel) {
232						limit = true
233					}
234				}
235			}
236		}
237		if limit {
238			cause = "usage-limit"
239		}
240		supervisorCause := cause
241		if cause == "" {
242			if runErr != nil {
243				return ReviewRunFailed, "the reviewer command failed: " + runErr.Error(), nil
244			}
245			return "", "", nil
246		}
247		// Without any continuity declaration, interruption classification is unknown.
248		if plan.Config.Limit == nil && plan.Config.Session == nil && plan.Config.Resume == nil {
249			cause = "unknown"
250		}
251		interruption := &ReviewInterruption{Cause: cause, Resumable: run.SessionDigest != "" && plan.Config.Resume != nil && len(plan.Config.Resume.Command) > 0}
252		if cause == "usage-limit" {
253			reset, e := captureReviewChannels(resetPattern(plan.Config), channels...)
254			if e != nil {
255				return "", "", e
256			}
257			if reset != "" {
258				t, e := time.Parse(time.RFC3339Nano, reset)
259				if e != nil {
260					return "", "", fmt.Errorf("adapter reset instant is not RFC3339")
261				}
262				interruption.ResetAt = t.UTC().Format(time.RFC3339Nano)
263			}
264		}
265		run.Interruption = interruption
266		return ReviewRunInterrupted, "review interrupted: " + cause + " (supervisor: " + supervisorCause + ")", nil
267	}
